SELECT COUNT(*) FROM sa_wrong_question
WHERE user_id = #{userId}
AND topic LIKE CONCAT('%', #{topic}, '%')
AND mastered = #{mastered}

SELECT id, user_id, question_id, topic, wrong_count, mastered, first_wrong_at, last_wrong_at
FROM sa_wrong_question
WHERE user_id = #{userId}
AND topic LIKE CONCAT('%', #{topic}, '%')
AND mastered = #{mastered}
ORDER BY last_wrong_at DESC, id DESC
LIMIT #{offset}, #{pageSize}
